func ExampleBam() string {
	sam := ExampleSam()
	var b strings.Builder
	view := exec.Command("samtools", "view", "-bS")
	view.Stdin = strings.NewReader(sam)
	view.Stdout = &b
	if e := view.Run(); e != nil {
		panic(e)
	}
	return b.String()
}

func ExampleSamN(n int) string {
	rawsam := ExampleSam()
	samLines := strings.Split(rawsam, "\n")
	samLines = samLines[:len(samLines)-1]
	samHead := samLines[:2]
	samEntries := samLines[2:]
	var b strings.Builder
	for _, line := range samHead {
		fmt.Fprintf(&b, "%v\n", line)
	}
	for i := 0; i < n; i++ {
		idx := i % len(samEntries)
		line := samEntries[idx]
		fmt.Fprintf(&b, "%v\n", line)
	}
	return b.String()
}

func ExampleBamN(n int) string {
	sam := ExampleSamN(n)
	var b strings.Builder
	view := exec.Command("samtools", "view", "-bS")
	view.Stdin = strings.NewReader(sam)
	view.Stdout = &b
	if e := view.Run(); e != nil {
		panic(e)
	}
	return b.String()
}

func SamtoolsAddRGPipe(r io.Reader, w io.Writer, name string) error {
	rgchange := fmt.Sprintf("@RG\tID:%v\tSM:%v", name, name)
	cmd := exec.Command("samtools", "addreplacerg", "-r", rgchange, "-o", "-", "-")
	cmd.Stdout = w
	cmd.Stderr = os.Stderr
	cmd.Stdin = r
	return cmd.Run()
}

func SamtoolsAddRGPipeIn(r io.Reader, out, name string) error {
	rgchange := fmt.Sprintf("@RG\tID:%v\tSM:%v", name, name)
	cmd := exec.Command("samtools", "addreplacerg", "-r", rgchange, "-o", out, "-")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = r
	return cmd.Run()
}

var gSamtoolsAddRG string

func BenchmarkSamtoolsAddRG(b *testing.B) {
	b.StopTimer()
	bam := ExampleBamN(b.N)

	in := strings.NewReader(bam)
	b.StartTimer()
	if e := SamtoolsAddRGPipeIn(in, "samtoolsaddrgtestout.bam", "banana"); e != nil {
		panic(e)
	}
	b.StopTimer()

	outraw, e := os.ReadFile("samtoolsaddrgtestout.bam")
	if e != nil {
		panic(e)
	}
	gSamtoolsAddRG = string(outraw)
}

var headerRe = regexp.MustCompile(`^@`)
var rgHeaderRe = regexp.MustCompile(`^@RG\tID:([^\t]*)\tSM:(.*)`)
var rgRe = regexp.MustCompile(`RG:([^\t]*)`)

func AddRGCore(r io.Reader, w io.Writer, name string) error {
	rgNewHeader := fmt.Sprintf("@RG\tID:%v\tSM:%v", name, name)
	s := bufio.NewScanner(r)
	s.Buffer([]byte{}, 1e15)
	wrotehead := false
	for s.Scan() {
		if headerRe.MatchString(s.Text()) {
			if rgHeaderRe.MatchString(s.Text()) {
				continue
			}
			if _, e := fmt.Fprintf(w, "%v\n", s.Text()); e != nil {
				return e
			}
			continue
		}

		if !wrotehead {
			wrotehead = true
			if _, e := fmt.Fprintf(w, "%v\n", rgNewHeader); e != nil {
				return e
			}
		}

		if rgRe.MatchString(s.Text()) {
			out := rgRe.ReplaceAllString(s.Text(), "RG:Z:" + name)
			if _, e := fmt.Fprintf(w, "%v\n", out); e != nil {
				return e
			}
		} else {
			if _, e := fmt.Fprintf(w, "%v\tRG:Z:%v\n", s.Text(), name); e != nil {
				return e
			}
		}
	}
	return s.Err()
}

func AddRGPipeIn(r io.Reader, out, name string) error {
	outf, e := os.Create(out)
	if e != nil {
		return e
	}
	defer func() {
		outf.Close()
	}()

	inr, inw := io.Pipe()
	outr, outw := io.Pipe()

	inview := exec.Command("samtools", "view", "-h")
	inview.Stdin = r
	inview.Stdout = inw
	inview.Stderr = os.Stderr
	if e := inview.Start(); e != nil {
		return e
	}

	go func() {
		if e := AddRGCore(inr, outw, name); e != nil {
			panic(e)
		}
		outw.Close()
	}()

	outview := exec.Command("samtools", "view", "-bS")
	outview.Stdin = outr
	outview.Stdout = outf
	outview.Stderr = os.Stderr
	if e := outview.Start(); e != nil {
		return e
	}

	e = inview.Wait()
	inw.Close()
	if e != nil {
		return e
	}
	e = outview.Wait()
	if e != nil {
		return e
	}

	return nil
}

func BenchmarkAddRG(b *testing.B) {
	b.StopTimer()
	bam := ExampleBamN(b.N)

	in := strings.NewReader(bam)
	b.StartTimer()
	if e := AddRGPipeIn(in, "addrgtestout.bam", "banana"); e != nil {
		panic(e)
	}
	b.StopTimer()

	outraw, e := os.ReadFile("addrgtestout.bam")
	if e != nil {
		panic(e)
	}
	gSamtoolsAddRG = string(outraw)
}

